import narration from './narration.json'

/**
 * Every narrated line with a stable key. The audio for key K lives in public/audio/K.mp3 and is generated by
 * scripts/gen-voice.mjs with the same keys (keep both in step: the script derives them the same way).
 */
export const N = narration

export function allLines(): Record<string, string> {
  const out: Record<string, string> = {}
  for (const [k, v] of Object.entries(N.mentor)) out[`mentor_${k}`] = v
  for (const [k, l] of Object.entries(N.lessons)) out[`lesson_${k}`] = `${l.title}. ${l.points.join(' ')}`
  N.life.forEach((e, i) => (out[`life_${i + 1}`] = `${e.title}. ${e.text}`))
  out.life_raise = `${N.raise.title}. ${N.raise.text}`
  for (const [k, list] of Object.entries(N.headlines)) list.forEach((h, i) => (out[`headline_${k}_${i}`] = h))
  return out
}
